func readEvents(input io.Reader, doFollow bool, includeTs bool, followW io.Writer) ([]Event, []string, error) {
	var events []Event
	var followLines []string
	scanner := bufio.NewScanner(input)
	// increase buffer for long lines
	const maxCapacity = 1024 * 1024
	buf := make([]byte, maxCapacity)
	scanner.Buffer(buf, maxCapacity)
	for scanner.Scan() {
		line := scanner.Text()
		// Try parse as JSON
		var e Event
		// Need to handle empty lines: json.Unmarshal("") fails, treat as bad
		if err := json.Unmarshal([]byte(line), &e); err != nil {
			// Check if no events yet -> ignore (and with follow, print raw?)
			if len(events) == 0 {
				// Check if line is empty/whitespace? Still print raw with follow? Our earlier follow leading bad printed "not json" raw. What about leading empty? Would it print empty line? Let's test: follow with leading empty – does it print blank line? Probably yes (prints raw line + "\n"). We'll do that.
				if doFollow && followW != nil {
					// print raw line + "\n" (even if empty? That would be just "\n")
					fmt.Fprintln(followW, line)
					followLines = append(followLines, line)
				}
				continue
			} else {
				// After events, error
				// Distinguish time parse error vs other?
				if strings.HasPrefix(err.Error(), "parsing time") {
					return events, followLines, err
				}
				// Check if error is due to Time field? json.Unmarshal for time.Time returns *time.ParseError, whose Error() starts with `parsing time`. Good.
				// For other JSON errors, return "no parsable events"
				return events, followLines, fmt.Errorf("no parsable events: Make sure to run go test with -json flag")
			}
		}
		// Valid JSON, append
		events = append(events, e)
		// Follow handling for valid Output events?
		if doFollow && followW != nil && e.Action == "output" {
			// Apply follow filter
			if shouldPrintFollow(e) {
				out := e.Output
				if includeTs {
					// Format time as "2006-01-02T15:04:05Z" (UTC, seconds)
					ts := e.Time.UTC().Format("2006-01-02T15:04:05Z")
					// If Time is zero (missing), Format gives "0001-01-01T00:00:00Z" – matches observed for missing Time.
					// For invalid? Already handled (would have errored). So ok.
					// Print timestamp + space + output (output already has newline? e.Output includes "\n" at end. Need to print timestamp + " " + output without extra newline? Our observed: "2024-01-01T00:00:02Z     log line\n" – timestamp + space + output (which is "    log line\n"). So fmt.Fprintf(followW, "%s %s", ts, out) where out includes newline. If out doesn't end with newline, need to add? Go test outputs always end with newline, but be safe: if not ending with \n, add.
					if strings.HasSuffix(out, "\n") {
						fmt.Fprintf(followW, "%s %s", ts, out)
					} else {
						fmt.Fprintf(followW, "%s %s\n", ts, out)
					}
					followLines = append(followLines, ts+" "+out)
				} else {
					// Print output as is (includes newline). If not ending with newline, add.
					if strings.HasSuffix(out, "\n") {
						fmt.Fprint(followW, out)
					} else {
						fmt.Fprintln(followW, out)
					}
					followLines = append(followLines, out)
				}
			}
		}
		// Also need to handle follow for invalid JSON after events? Already returned error without printing raw. For leading bad, printed raw. Good.
		// What about valid JSON but not Output (e.g., run/pass)? Follow doesn't print those. Good.
	}
	if err := scanner.Err(); err != nil {
		// Scanner error (e.g., line too long?) Treat as?
		if len(events) == 0 {
			return events, followLines, fmt.Errorf("no parsable events: Make sure to run go test with -json flag")
		}
		return events, followLines, fmt.Errorf("no parsable events: Make sure to run go test with -json flag")
	}
	return events, followLines, nil
}

func shouldPrintFollow(e Event) bool {
	out := e.Output
	// Filter === RUN, PAUSE, CONT (with exact prefixes)
	if strings.HasPrefix(out, "=== RUN   ") || strings.HasPrefix(out, "=== PAUSE ") || strings.HasPrefix(out, "=== CONT  ") {
		return false
	}
	// Filter --- PASS and --- SKIP (with space after colon), but not FAIL
	if strings.HasPrefix(out, "--- PASS: ") || strings.HasPrefix(out, "--- SKIP: ") {
		return false
	}
	// Also need to handle indented? No, follow filtering for --- PASS/SKIP: does it check after trimming leading spaces? Our earlier test for fail details showed header detection trims leading spaces, but follow filtering? Let's test: follow with "    --- PASS: TestX" (indented) – is it filtered? We haven't tested. For now, assume prefix check without trimming (as observed for "=== RUN" etc. which require start). But what about "    --- PASS"? Probably not filtered (since indented, not at start). We'll assume no trim.
	// Filter bare PASS/FAIL for package-level only (Test == "")
	if e.Test == "" {
		trimmed := strings.TrimSpace(out)
		if trimmed == "PASS" || trimmed == "FAIL" {
			return false
		}
	}
	return true
}

