	trimmed := strings.TrimLeft(out, " \t")
	// Count leading dashes
	i := 0
	for i < len(trimmed) && trimmed[i] == '-' {
		i++
	}
	if i < 3 {
		return false
	}
	// After dashes, must be exactly 1 space, then "FAIL: ", with space after colon
	rest := trimmed[i:]
	// Must start with " FAIL: " (space + FAIL: + space)
	if !strings.HasPrefix(rest, " FAIL: ") {
		return false
	}
	return true
}

