	if !pk.hasPkgEvent {
		return 0
	}
	if pk.pkgAction == "skip" && !pk.isNotest {
		// Empty skip: summary elapsed 0 (as observed)
		return 0
	}
	return pk.pkgElapsed
}

func getCoverVal(pk *PackageInfo) (float64, bool) {
	if pk.hasPanic {
		return 0, false
	}
	if pk.isNotest {
		return 0, false
	}
	if pk.coverStr == "" {
		return 0, false
	}
	return pk.coverVal, true
}

func pkgsCompletionOrder(events []Event, pkgs map[string]*PackageInfo) []string {
	// Order of package completion (package event order) as they appear in events
	// For packages without pkg event (empty), they have no completion, so not included? Progress never shows empty, so fine.
	var order []string
	seen := make(map[string]bool)
	for _, e := range events {
		if e.Test == "" && (e.Action == "pass" || e.Action == "fail" || e.Action == "skip") {
			if !seen[e.Package] {
				seen[e.Package] = true
				order = append(order, e.Package)
			}
		}
	}
	return order
