func isFailHeader(out string) bool {
	// Check if output is FAIL header: after trimming leading spaces/tabs, check for ^-{3,} FAIL:  (at least 3 dashes, exactly 1 space, "FAIL: ", with space after colon)
	// Also need to handle dashes normalization? Detection allows >=3 dashes, exactly 1 space between dashes and FAIL, and "FAIL: " with space.
	trimmed := strings.TrimLeft(out, " \t")
	// Count leading dashes
	i := 0
	for i < len(trimmed) && trimmed[i] == '-' {
		i++
	}
	if i < 3 {
		return false
	}
	// After dashes, must be exactly 1 space, then "FAIL: ", with space after colon
	rest := trimmed[i:]
	// Must start with " FAIL: " (space + FAIL: + space)
	if !strings.HasPrefix(rest, " FAIL: ") {
		return false
	}
	return true
}

