    fmt.Println(smallDisplay(pkgs))
}
func smallDisplay(pkgs []string) map[string]string {
    if len(pkgs)==1 {
        // basename
        p:=pkgs[0]
        if idx:=strings.LastIndex(p,"/"); idx!=-1 {
            return map[string]string{p: p[idx+1:]}
        }
        return map[string]string{p:p}
    }
    // find longest common prefix
    prefix:=pkgs[0]
    for _,p:=range pkgs[1:] {
        // common of prefix and p
        i:=0
        for i<len(prefix) && i<len(p) && prefix[i]==p[i] {
            i++
        }
        prefix=prefix[:i]
    }
    fmt.Printf("common %q\n",prefix)
    // find last "/" in prefix
    lastSlash:=strings.LastIndex(prefix,"/")
    if lastSlash==-1 {
        // basenames
        m:=map[string]string{}
        for _,p:=range pkgs {
            if idx:=strings.LastIndex(p,"/"); idx!=-1 {
                m[p]=p[idx+1:]
            } else {
                m[p]=p
            }
        }
        return m
    }
    // remove prefix up to slash
    cut:=lastSlash+1
    m:=map[string]string{}
    for _,p:=range pkgs {
        m[p]=p[cut:]
    }
    return m
}
