// Helpers for colors
func colorStatus(status string, useColor bool) string {
	if !useColor {
		return status
	}
	switch status {
	case "PASS":
		return "\x1b[92mPASS\x1b[0m"
	case "FAIL":
		return "\x1b[91mFAIL\x1b[0m"
	case "SKIP":
		return "\x1b[93mSKIP\x1b[0m"
	case "PANIC":
		return "\x1b[91mPANIC\x1b[0m"
	case "NOTEST":
		return "\x1b[93mNOTEST\x1b[0m"
	default:
		return status
	}
}

func colorCover(coverStr string, coverVal float64, useColor bool) string {
	if !useColor || coverStr == "" || coverStr == "--" {
		if coverStr == "" {
			return "--"
		}
		return coverStr
	}
	// 0.0% no color
	if coverVal == 0 {
		return coverStr
	}
	if coverVal <= 50 {
		return "\x1b[91m" + coverStr + "\x1b[0m"
	} else if coverVal < 80 {
		return "\x1b[93m" + coverStr + "\x1b[0m"
	} else {
		return "\x1b[92m" + coverStr + "\x1b[0m"
	}
}

func colorCoverWithDelta(coverStr string, coverVal float64, deltaStr string, useColor bool) string {
	// coverStr like "90.0%", deltaStr like "(+80.0%)" or "(0.0%)" etc. Combined "90.0% (+80.0%)"
	combined := coverStr + " " + deltaStr
	if !useColor {
		return combined
	}
	if coverVal == 0 {
		return combined
	}
	if coverVal <= 50 {
		return "\x1b[91m" + combined + "\x1b[0m"
	} else if coverVal < 80 {
		return "\x1b[93m" + combined + "\x1b[0m"
	} else {
		return "\x1b[92m" + combined + "\x1b[0m"
	}
}

// visible length ignoring ANSI codes
func visibleLen(s string) int {
	// remove \x1b[...m sequences
	inEsc := false
	count := 0
	for i := 0; i < len(s); i++ {
		if s[i] == '\x1b' && i+1 < len(s) && s[i+1] == '[' {
			inEsc = true
			i++ // skip '['
			continue
